"""Spec-aware state I/O for synaptory pipeline-state.json.

This module is the single chokepoint that hides the v2 (single-spec flat)
vs v3 (multi-spec nested) on-disk layout from the lifecycle state machines.

Layouts (see docs/multi-spec-design.md §5.2):

  v2.0 — legacy flat:
    {
      "version": "2.0",
      "build_mode": "scrum",
      "lifecycle_state": "SPRINT_EXECUTION",
      "current_sprint": 9,
      "current_stories": [...],
      ...
    }

  v3.0 — multi-spec nested:
    {
      "version": "3.0",
      "build_mode": "scrum",
      "active_spec": "platform",
      "specs": {
        "platform":         { lifecycle_state, current_sprint, current_stories, ... },
        "contract-mastery": { ... },
        "ehr-integration":  { ... }
      }
    }

Callers see the same flat shape in both modes. In v3, read_state() returns
a copy of the spec's sub-state with two breadcrumb keys, `_spec_id` and
`_multispec=True`, which write_state() consumes to merge changes back into
the right slot in the full file before the atomic rename.

Atomic-write contract: write_state() always writes the full file via
temp-file + os.replace(). In multi-spec mode, the read-modify-write window
is racy across processes (lost updates on the *unchanged* parts of other
specs are not possible because each writer re-reads the full file just
before serializing, but lost updates within the *same* spec by truly
concurrent writers can happen — file-level locking would be needed for
that. Acceptable per design §11.3 because real-world concurrent transitions
target different specs).
"""

from __future__ import annotations

import contextlib
import json
import os
from typing import Iterator, Optional


import state_store as _store

_SPEC_ID_KEY = "_spec_id"
_MULTISPEC_KEY = "_multispec"


# ── primitives, shared with the SPQ store ────────────────────────────────────
# These moved to `state_store` when SPQ stopped borrowing this module
# (#303/#304/#305). Both stores need identical locking and atomic-write
# guarantees, and the flock re-entrancy rule is subtle enough that a second copy
# would drift. The names below are kept so every existing call site is
# untouched; only the implementation moved.

StateLockTimeout = _store.StateLockTimeout
_LOCK_TIMEOUT_S = _store.LOCK_TIMEOUT_S
_LOCK_POLL_S = _store.LOCK_POLL_S
_file_lock = _store.file_lock


@contextlib.contextmanager
def state_transaction(project_dir: str, timeout: float = _LOCK_TIMEOUT_S) -> Iterator[None]:
    """Hold the pipeline-state lock across a whole read-modify-write window.

    `write_state` locks only its own re-read-and-merge, which protects
    concurrent writers targeting *different* specs but leaves every caller's
    read → check → mutate → write window unprotected. Two concurrent advances
    could therefore both read the same state, both pass the replay-ledger
    check, and both write: a lost update and a defeated anti-replay guard.

    Wrap the entire window instead:

        with state_transaction(project_dir):
            state = read_state(project_dir)
            ...                       # checks that depend on that state
            write_state(project_dir, state)

    Raises StateLockTimeout if another holder does not release in time.
    """
    with _store.transaction(_lock_path(project_dir), timeout=timeout):
        yield


def _lock_path(project_dir: str) -> str:
    return os.path.join(
        project_dir, ".synaptory", ".orchestrator", "pipeline-state.json.lock"
    )


def state_path(project_dir: str) -> str:
    return os.path.join(project_dir, ".synaptory", ".orchestrator", "pipeline-state.json")


def _now() -> str:
    return _store.now_iso()


def read_full_state(project_dir: str) -> dict:
    """Return the raw file contents. Empty dict if the file is missing/invalid."""
    return _store.read_json(state_path(project_dir))


def write_full_state(project_dir: str, state: dict) -> None:
    """Write the raw file atomically (temp + os.replace)."""
    _store.write_json_atomic(state_path(project_dir), state)


def is_multispec(full_state: dict) -> bool:
    return full_state.get("version") == "3.0" and isinstance(full_state.get("specs"), dict)


def get_active_spec(project_dir: str) -> Optional[str]:
    """Return the current active_spec, or None in single-spec / unset cases."""
    full = read_full_state(project_dir)
    active = full.get("active_spec")
    return active if isinstance(active, str) and active else None


def set_active_spec(project_dir: str, spec_id: str) -> None:
    """Persist `active_spec` in the top-level state file."""
    full = read_full_state(project_dir)
    full["active_spec"] = spec_id
    write_full_state(project_dir, full)


def read_state(
    project_dir: str,
    spec_id: Optional[str] = None,
    default_state_factory=None,
) -> dict:
    """Return a flat spec-state view ready for a state machine to read/mutate.

    Single-spec (v2 or empty file): returns the flat top-level dict.
    Multi-spec (v3):                returns a copy of `specs[<spec_id>]` with
                                    `_spec_id` and `_multispec=True` breadcrumbs.

    `spec_id` falls back to the file's `active_spec` field. In multi-spec mode
    a spec slot is auto-initialized (via `default_state_factory`) on first read.

    Raises:
        ValueError on missing/invalid state.
    """
    full = read_full_state(project_dir)
    if not full:
        if default_state_factory is None:
            return {}
        return default_state_factory()

    if is_multispec(full):
        resolved = spec_id or full.get("active_spec")
        if not resolved:
            raise ValueError(
                "multi-spec state but neither spec_id was passed nor "
                "active_spec is set in the state file"
            )
        specs = full.setdefault("specs", {})
        if resolved not in specs:
            # Auto-seed an INCEPTION slot for a brand-new spec — write back
            # immediately so concurrent readers see a consistent file.
            seed = default_state_factory() if default_state_factory else {}
            specs[resolved] = seed
            write_full_state(project_dir, full)
        view = dict(specs[resolved])
        view[_SPEC_ID_KEY] = resolved
        view[_MULTISPEC_KEY] = True
        return view

    # v2 flat layout
    return full


def write_state(project_dir: str, state: dict) -> None:
    """Persist a state dict produced by `read_state` (or `default_state_factory`).

    Strips the multi-spec breadcrumbs before writing. In multi-spec mode,
    re-reads the full file, replaces the spec's slot, and writes back —
    so changes to other specs by concurrent writers are not clobbered
    *as long as those writers also re-read just before writing*.

    The breadcrumbs are read with `.get()` (not `.pop()`) and stripped into
    a copy, so this is **non-mutating** w.r.t. the caller's dict. That is
    load-bearing for callers that write the *same* dict more than once —
    e.g. `scrum_state_machine.transition_story` writes, runs DoD eval, then
    writes again. A mutating `.pop()` here dropped the breadcrumbs on the
    first write, so the second write fell through to the flat-write branch
    and clobbered the `{version, active_spec, specs:{}}` envelope, deleting
    every other spec (issue #24, Bug A).
    """
    spec_id = state.get(_SPEC_ID_KEY)
    is_multi = state.get(_MULTISPEC_KEY, False)
    clean = {k: v for k, v in state.items()
             if k not in (_SPEC_ID_KEY, _MULTISPEC_KEY)}

    if is_multi and spec_id:
        # Serialize the read-modify-write window with an advisory file lock so
        # concurrent writers targeting *different* specs in the same file
        # don't lose each other's updates (verification §11.3). Same-spec
        # concurrent writes still rely on last-writer-wins semantics — that
        # would need a higher-level coordination layer.
        with _file_lock(_lock_path(project_dir)):
            full = read_full_state(project_dir) or {
                "version": "3.0",
                "build_mode": clean.get("build_mode", "scrum"),
                "specs": {},
            }
            full.setdefault("specs", {})[spec_id] = clean
            if "version" not in full:
                full["version"] = "3.0"
            write_full_state(project_dir, full)
    else:
        write_full_state(project_dir, clean)


def upgrade_v2_to_v3(project_dir: str, primary_spec_id: str) -> dict:
    """Wrap an existing v2 flat state under `specs.<primary_spec_id>`.

    Idempotent: if the file is already v3, returns it unchanged.
    Used by the migration script (migrate_to_multispec.py).
    """
    full = read_full_state(project_dir)
    if not full:
        return {}
    if is_multispec(full):
        return full

    # Pull the per-spec fields up into a sub-dict, leave global metadata at top.
    build_mode = full.get("build_mode", "scrum")
    spec_substate = {k: v for k, v in full.items() if k not in ("version", "build_mode")}

    new_state = {
        "version": "3.0",
        "build_mode": build_mode,
        "active_spec": primary_spec_id,
        "specs": {primary_spec_id: spec_substate},
        "upgraded_from": "2.0",
        "upgraded_at": _now(),
    }
    write_full_state(project_dir, new_state)
    return new_state
